{
  "decision-allocate-two-review-desks": "WITH eligible AS (SELECT notice_ref, bout_id, desk_minutes, abs(posted_pts - witness_pts) AS discrepancy FROM discrepancy_notices WHERE witness_pts IS NOT NULL) SELECT a.notice_ref AS first_ref, b.notice_ref AS second_ref, a.discrepancy + b.discrepancy AS points_at_issue, a.desk_minutes + b.desk_minutes AS total_minutes FROM eligible AS a JOIN eligible AS b ON a.notice_ref COLLATE BINARY < b.notice_ref AND a.bout_id <> b.bout_id WHERE a.desk_minutes + b.desk_minutes <= 10 ORDER BY points_at_issue DESC, total_minutes ASC, first_ref COLLATE BINARY ASC, second_ref COLLATE BINARY ASC LIMIT 1",
  "decision-apply-meal-tip-policy-at-service-date": "WITH caps AS (SELECT m.meal_id, m.tip_cents, p.source_id, (m.food_cents + CASE WHEN p.base_kind = 'gross' THEN m.tax_cents ELSE 0 END) * p.cap_bp / 10000 AS cap_cents FROM meal_claim AS m JOIN policy_notice AS p ON p.source_id = (SELECT n.source_id FROM policy_notice AS n WHERE n.program_code = m.program_code AND n.effective_day <= m.service_day ORDER BY n.effective_day DESC LIMIT 1)) SELECT meal_id, tip_cents - cap_cents AS reduction_cents, source_id FROM caps WHERE tip_cents > cap_cents ORDER BY meal_id ASC",
  "decision-apply-one-pass-folder-moves": "SELECT coalesce((SELECT m.next_dir || substr(f.prior_path, length(m.prior_dir) + 1) FROM folder_move AS m WHERE substr(f.prior_path, 1, length(m.prior_dir) + 1) COLLATE BINARY = (m.prior_dir || '/') ORDER BY length(m.prior_dir) DESC LIMIT 1), f.prior_path) AS final_path, f.asset_tag AS asset_tag FROM asset_file AS f ORDER BY final_path COLLATE BINARY ASC",
  "decision-apply-remittance-to-open-invoices": "WITH available AS (SELECT i.account_code, i.invoice_code, i.due_day, i.open_cents, r.payment_cents - coalesce(sum(i.open_cents) OVER (PARTITION BY i.account_code ORDER BY i.due_day, i.invoice_code COLLATE BINARY ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0) AS cash_left FROM open_invoice AS i JOIN remittance_batch AS r ON r.account_code = i.account_code WHERE i.hold_note IS NULL AND i.open_cents > 0), applied AS (SELECT account_code, invoice_code, due_day, open_cents, min(open_cents, cash_left) AS applied_cents FROM available WHERE cash_left > 0) SELECT account_code, invoice_code, applied_cents, open_cents - applied_cents AS remaining_open_cents FROM applied ORDER BY account_code COLLATE BINARY ASC, due_day ASC, invoice_code COLLATE BINARY ASC"
}
